test("Saved Compilation schema 1 round-trips explicit recipe intent without prose", () => {
  const fixture = savedCompilationFixture(); const storage = serialiseSavedCompilations({ schemaVersion: 1, entries: [fixture] }); const repaired = repairSavedCompilationsStorage(storage);
  assert.equal(repaired.repaired, 0); assert.equal(repaired.dropped, 0); assert.deepEqual(repaired.storage, storage); assert.equal(repaired.storage.entries[0].recipe.overrides[0].included, false); assert.equal(repaired.storage.entries[0].output.format, "docx");
  const persisted = JSON.stringify(storage); assert.doesNotMatch(persisted, /"(?:content|paragraph|book|blobUrl|outputDestination|frontmatter)"\s*:/i); for (const forbidden of ["file:///", "/Users/"]) assert.doesNotMatch(persisted, new RegExp(forbidden, "i"));
});
test("Saved Compilation repair isolates malformed entries, repairs duplicate IDs, and preserves legacy settings", () => {
  const first = savedCompilationFixture(); const duplicate = { ...savedCompilationFixture(), name: "ARC EPUB", output: { ...savedCompilationFixture().output, format: "epub", filename: "ARC.epub" } };
  const repaired = repairSavedCompilationsStorage({ schemaVersion: 1, entries: [first, duplicate, { id: "bad" }] });
  assert.equal(repaired.storage.entries.length, 2); assert.notEqual(repaired.storage.entries[0].id, repaired.storage.entries[1].id); assert.equal(repaired.dropped, 1);
  const legacy = { ...DEFAULT_SETTINGS, savedCompilations: undefined } as never; const migrated = repairSettings(legacy); assert.deepEqual(migrated.savedCompilations, { schemaVersion: 1, entries: [] }); assert.equal(migrated.profiles.length > 0, true);
});
test("Saved Compilation storage rejects unknown schemas and bounds malicious collections", () => {
  const fixture = savedCompilationFixture(); const unknown = repairSavedCompilationsStorage({ schemaVersion: 99, entries: [fixture] }); assert.equal(unknown.unsupportedSchema, true); assert.deepEqual(unknown.storage.entries, []);
  const oversized = repairSavedCompilationsStorage({ schemaVersion: 1, entries: Array.from({ length: MAX_SAVED_COMPILATIONS + 2 }, (_, index) => ({ ...fixture, id: "saved-" + index })) }); assert.equal(oversized.storage.entries.length, MAX_SAVED_COMPILATIONS); assert.equal(oversized.dropped, 2);
  const referenceHeavy = savedCompilationFixture(); referenceHeavy.observedSource.references = Array.from({ length: MAX_SAVED_COMPILATION_REFERENCES + 1 }, (_, index) => ({ path: "Chapter/" + index + ".md", parentPath: "Chapter", name: index + ".md", kind: "note" as const, expectedRole: "scene" as const })); const bounded = repairSavedCompilationsStorage({ schemaVersion: 1, entries: [referenceHeavy] }); assert.equal(bounded.storage.entries[0].observedSource.references.length, MAX_SAVED_COMPILATION_REFERENCES);
});
test("Saved Compilation recipe comparison is deterministic and ignores observed/export facts", () => {
  const first = savedCompilationFixture(); const reordered = { ...savedCompilationFixture(), recipe: { ...savedCompilationFixture().recipe, overrides: [...savedCompilationFixture().recipe.overrides].reverse() }, observedSource: { sourceFingerprint: "later", inputSignature: "later", references: [] }, lastSuccessfulExport: undefined };
  assert.equal(savedCompilationRecipeEquals(first, reordered), true); assert.equal(savedCompilationRecipeSignature(first), savedCompilationRecipeSignature(reordered)); reordered.output.filename = "Different.docx"; assert.equal(savedCompilationRecipeEquals(first, reordered), false);
});
const savedService = (entries: SavedCompilation[] = [], save: () => Promise<void> = async () => undefined): SavedCompilationService => {
  const settings = { ...DEFAULT_SETTINGS, savedCompilations: { schemaVersion: 1, entries } };
  const service = new SavedCompilationService(() => settings, save, (() => 100) as () => number, (() => "saved-service-id") as () => string); service.initialize(); return service;
};
const savedInput = (name = "Editor DOCX") => { const item = savedCompilationFixture(); return { name, description: item.description, root: item.root, recipe: item.recipe, output: item.output, observedSource: item.observedSource }; };
test("Saved Compilation service creates, lists, protects copies, and permits duplicate names", async () => {
  const service = savedService(); const first = await service.create(savedInput()); const second = await service.create(savedInput());
  assert.equal(first.status, "ok"); assert.equal(second.status, "ok"); if (first.status !== "ok" || second.status !== "ok") return;
  assert.notEqual(first.compilation.id, second.compilation.id); assert.equal(service.listForRoot("Books/Synthetic").length, 2); const listed = service.listAll(); listed[0].name = "mutated"; assert.notEqual(service.getById(first.compilation.id)?.name, "mutated"); assert.equal(service.getById("missing"), undefined);
});
test("Saved Compilation service updates, renames, reassociates, tracks opening, and records only matching export facts", async () => {
  const service = savedService(); const created = await service.create(savedInput()); if (created.status !== "ok") return assert.fail("create failed"); const id = created.compilation.id;
  const changed = await service.saveChanges(id, { recipe: { ...created.compilation.recipe, includeBackMatter: true }, output: { ...created.compilation.output, filename: "Changed.docx" }, observedSource: created.compilation.observedSource }); assert.equal(changed.status, "ok");
  const renamed = await service.rename(id, "Renamed"); assert.equal(renamed.status, "ok"); const root = await service.reassociateRoot(id, "Books/Reassociated"); assert.equal(root.status, "ok"); const opened = await service.markLastOpened(id); assert.equal(opened.status, "ok");
  const current = service.getById(id)!; assert.equal(current.createdAt, 100); assert.equal(current.name, "Renamed"); assert.equal(current.root.path, "Books/Reassociated"); assert.equal(current.output.filename, "Changed.docx");
  assert.equal((await service.recordSuccessfulExport(id, { timestamp: 101, format: "docx", sourceFingerprint: "source", inputSignature: "input", recipeSignature: "wrong" })).status, "recipe-mismatch");
  assert.equal((await service.recordSuccessfulExport(id, { timestamp: 101, format: "docx", sourceFingerprint: "source", inputSignature: "input", recipeSignature: savedCompilationRecipeSignature(current) })).status, "ok");
});
