const reconciliationPlan = (extra: ContentPlanItem[] = []): ContentPlanItem[] => [
  { path: "Books/Synthetic/Chapter 1", parentPath: "Books/Synthetic", name: "Chapter 1", kind: "folder", role: "chapter", detectedRole: "chapter", included: true, order: 0 },
  { path: "Books/Synthetic/Chapter 1/Scene 1.md", parentPath: "Books/Synthetic/Chapter 1", name: "Scene 1", kind: "note", role: "scene", detectedRole: "scene", included: true, order: 0 },
  { path: "Books/Synthetic/Chapter 1/Scene 2.md", parentPath: "Books/Synthetic/Chapter 1", name: "Scene 2", kind: "note", role: "scene", detectedRole: "scene", included: true, order: 1 }, ...extra
];
const reconciliationCompilation = (): SavedCompilation => {
  const compilation = savedCompilationFixture(); compilation.observedSource.references = [
    { path: "Chapter 1", parentPath: "_root", name: "Chapter 1", kind: "folder", expectedRole: "chapter", fingerprint: "chapter" },
    { path: "Chapter 1/Scene 1.md", parentPath: "Chapter 1", name: "Scene 1", kind: "note", expectedRole: "scene", fingerprint: "a1b2" },
    { path: "Chapter 1/Scene 2.md", parentPath: "Chapter 1", name: "Scene 2", kind: "note", expectedRole: "scene", fingerprint: "b2c3" }
  ]; return compilation;
};
const includedReconciliationCompilation = (): SavedCompilation => {
  const compilation = reconciliationCompilation(); const override = compilation.recipe.overrides[0];
  if (override) { override.included = true; override.role = "scene"; }
  return compilation;
};
