test("Part 8E polish contract: Part 8 documentation records management safety", async () => {
  const [readme, architecture, guide, manual] = await Promise.all(["README.md", "ARCHITECTURE.md", "DEVELOPER_GUIDE.md", "MANUAL_TESTING.md"].map(async (file) => await readFile(file, "utf8")));
  assert.match(readme, /Manage…/); assert.match(architecture, /Parts 7–8 complete/); assert.match(guide, /Parts 1–8 are complete/); assert.match(manual, /Delete inactive, current clean, current dirty/);
});
test("release audit: Saved review UI uses ES2018-compatible path indexing", async () => {
  const source = await readFile("src/workspace/saved-compilation-review.ts", "utf8");
  assert.doesNotMatch(source, /\.at\(/);
  assert.match(source, /finding\.path\.split\("\/"\)\.pop\(\)/);
});
test("release audit: management focus does not render immutable IDs into DOM attributes", async () => {
  const source = await readFile("src/compile-modal.ts", "utf8");
  assert.doesNotMatch(source, /data-compilation-id/);
  assert.match(source, /managementActionTargets/);
});

let failures = 0;
for (const [name, action] of tests) { try { await action(); process.stdout.write(`✓ ${name}\n`); } catch (error) { failures += 1; process.stderr.write(`✗ ${name}\n${error instanceof Error ? error.stack : String(error)}\n`); } }
if (failures) process.exitCode = 1; else process.stdout.write(`${tests.length} tests passed.\n`);
